# -*- coding: utf-8 -*-
"""
Converts a Zoom meeting summary (markdown) into a conservative Confluence-safe
HTML fragment (deterministic replacement for the Deep Reasoning HTML assistant).

Input (wired via input_map, not templated inside this code string):
  meeting = trigger.meeting    # the raw Zoom meeting object

Reads meeting.summary.summaryContent (markdown) and meeting.meeting_topic.

Whitelisted tags only: h2 h3 p ul li strong em  (table tags supported if the
source already contains pipe tables). NO a/div/span/br/img/code/pre, NO inline
styles/class/id, NO macros. Nested lists are flattened to one level.

Outputs (flat strings):
  page_title : "<Meeting Name> - Meeting Summary - YYYYMMDDHHMMSS"
  page_body  : Confluence-safe HTML fragment (AI disclaimer appended last)

STRICT: content is used exactly as provided; nothing is inferred or fabricated.
"""

import json
import re
from datetime import datetime

DISCLAIMER = ("<p><em>Generated by AI. AI can make mistakes. "
              "Review for accuracy.</em></p>")


def _coerce_obj(obj):
    if isinstance(obj, dict):
        return obj
    if isinstance(obj, str):
        s = obj.strip()
        if not s:
            return {}
        try:
            v = json.loads(s)
            return v if isinstance(v, dict) else {}
        except Exception:
            return {}
    return {}


def _text(v):
    return "" if v is None else str(v).strip()


def _escape(t):
    return (str(t).replace("&", "&amp;").replace("<", "&lt;")
            .replace(">", "&gt;").replace('"', "&quot;"))


def _inline(t):
    """Escape text, then map a safe subset of inline markdown to whitelisted tags."""
    t = _escape(t)
    # markdown link [text](url) -> "text: url" (links must be plain text, no <a>)
    t = re.sub(r"\[([^\]]+)\]\((https?://[^)\s]+)\)", r"\1: \2", t)
    # inline code -> plain text (no <code>)
    t = re.sub(r"`([^`]+)`", r"\1", t)
    # bold before italic
    t = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", t)
    t = re.sub(r"__(.+?)__", r"<strong>\1</strong>", t)
    t = re.sub(r"\*([^*\n]+?)\*", r"<em>\1</em>", t)
    t = re.sub(r"(?<![\w*])_([^_\n]+?)_(?![\w*])", r"<em>\1</em>", t)
    return t.strip()


def _md_to_html(md):
    lines = str(md).replace("\r\n", "\n").replace("\r", "\n").split("\n")
    out, para, items = [], [], []

    def flush_para():
        if para:
            txt = _inline(" ".join(x.strip() for x in para).strip())
            if txt:
                out.append("<p>" + txt + "</p>")
            para.clear()

    def flush_list():
        if items:
            cells = "".join("<li>" + _inline(x) + "</li>" for x in items if x.strip())
            if cells:
                out.append("<ul>" + cells + "</ul>")
            items.clear()

    for raw in lines:
        stripped = raw.strip()
        if not stripped:
            flush_para(); flush_list(); continue
        h = re.match(r"^(#{1,6})\s+(.*)$", stripped)
        if h:
            flush_para(); flush_list()
            tag = "h2" if len(h.group(1)) <= 2 else "h3"
            txt = _inline(h.group(2).strip())
            if txt:
                out.append("<%s>%s</%s>" % (tag, txt, tag))
            continue
        b = re.match(r"^[-*+•]\s+(.*)$", stripped)
        if b:
            flush_para()
            items.append(b.group(1).strip())
            continue
        n = re.match(r"^\d+[.)]\s+(.*)$", stripped)
        if n:
            flush_para()
            items.append(n.group(1).strip())
            continue
        flush_list()
        para.append(stripped)

    flush_para(); flush_list()
    return "".join(out)


def _title(meeting):
    topic = _text(meeting.get("meeting_topic") or meeting.get("topic")) or "Meeting"
    ts = datetime.now().strftime("%Y%m%d%H%M%S")
    return "%s - Meeting Summary - %s" % (topic, ts)


def run_node(input_data, context):
    try:
        if not isinstance(input_data, dict):
            input_data = {}
        meeting = _coerce_obj(input_data.get("meeting"))
        summary = _coerce_obj(meeting.get("summary"))
        content = _text(summary.get("summaryContent"))
        body = _md_to_html(content) if content else ""
        if not body:
            pt = _text(summary.get("plainText"))
            body = "<p>" + _escape(pt) + "</p>" if pt else ""
        page_body = body + DISCLAIMER
        return {"success": True, "output": {
            "page_title": _title(meeting),
            "page_body": page_body,
        }}
    except Exception as exc:
        return {"success": False, "output": {"error": str(exc)}}


if __name__ == "__main__":
    from pathlib import Path
    try:
        request = json.loads(Path(__file__).with_name("request.json").read_text(encoding="utf-8"))
        result = run_node(request.get("input_data", {}), request.get("context", {}))
    except Exception as exc:
        result = {"success": False, "output": {"error": str(exc)}}
    print(json.dumps(result, ensure_ascii=False))
